function nivelAmericano(v) {
  if (v <= 50) return "boa";
  if (v <= 100) return "moderada";
  if (v <= 150) return "ruim para grupos sensíveis";
  if (v <= 200) return "ruim";
  if (v <= 300) return "muito ruim";
  return "perigosa";
}

function nivelEuropeu(v) {
  if (v <= 20) return "boa";
  if (v <= 40) return "razoável";
  if (v <= 60) return "moderada";
  if (v <= 80) return "ruim";
  if (v <= 100) return "muito ruim";
  return "extremamente ruim";
}

async function run() {
  const europeu = params.indice.indexOf("europeu") === 0;
  const campo = europeu ? "european_aqi" : "us_aqi";
  const a = await http.getJSON("https://air-quality-api.open-meteo.com/v1/air-quality?latitude=" + params.cidade.latitude + "&longitude=" + params.cidade.longitude + "&current=us_aqi,european_aqi,pm2_5,pm10&timezone=auto");
  const c = a && a.current;
  if (!c || typeof c[campo] !== "number") {
    log("Índice de qualidade do ar indisponível.");
    return;
  }
  const valor = Math.round(c[campo]);
  if (valor <= params.limite) {
    log("Qualidade do ar " + valor + ", dentro do limite de " + params.limite + ".");
    return;
  }
  const nivel = europeu ? nivelEuropeu(valor) : nivelAmericano(valor);
  let text = "😷 Ar " + nivel + " em " + params.cidade.name + ": índice " + valor + " (" + (europeu ? "europeu" : "americano") + ", limite " + params.limite + ")";
  if (typeof c.pm2_5 === "number") text += ". PM2,5: " + (Math.round(c.pm2_5 * 10) / 10).toString().replace(".", ",") + " µg/m³";
  text += ". Evite exercícios ao ar livre.";
  await notify.send({text});
}
